"""Проверка Space Soundscape, Family Connection и Mission Games: python3 tests/wellness.py (playwright + chromium)."""
import asyncio,pathlib,sys,os
from playwright.async_api import async_playwright
ROOT=pathlib.Path(__file__).resolve().parent;URL=(ROOT.parent/'index.html').as_uri();CREW=(ROOT.parent/'crew.html').as_uri();OUT=ROOT/'shots';OUT.mkdir(exist_ok=True)
EXE='/opt/pw-browsers/chromium' if os.path.exists('/opt/pw-browsers/chromium') else None
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(executable_path=EXE,args=['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--autoplay-policy=no-user-gesture-required','--use-fake-ui-for-media-stream','--use-fake-device-for-media-stream'])
        ctx=await b.new_context(viewport={'width':1440,'height':900},locale='ru-RU',permissions=['microphone']);pg=await ctx.new_page();errs=[];R=[]
        pg.on('pageerror',lambda e:errs.append(str(e)));pg.on('console',lambda m:errs.append(m.text) if m.type=='error' else None)
        ok=lambda n,c,x='':R.append((n,c,x))
        await pg.goto(URL);await pg.wait_for_selector('#spPlayer .spMain');await pg.wait_for_timeout(1500)
        # плеер: автостарта нет
        ok('музыка не включается сама',await pg.evaluate('SP.a.paused&&!SP.a.src'))
        await pg.click('#spPlayer .spMain');await pg.wait_for_timeout(2500)
        t=await pg.evaluate('SP.a.currentTime');ok('встроенный трек Deep Space играет после нажатия',t>0.5 and await pg.evaluate('!SP.a.paused'),round(t,2))
        ok('волны анимируются',await pg.evaluate("(()=>{return [...document.querySelectorAll('.spWave i')].some(i=>i.style.transform&&i.style.transform!=='scaleY(.18)'&&i.style.transform!=='scaleY(0.18)')})()"))
        await pg.click('#spPlayer .spNow');await pg.click('[data-spc=focus]');await pg.wait_for_timeout(1800)
        ok('категория Focus Mode переключает трек и продолжает играть',await pg.evaluate("SP.st.cat==='focus'&&!SP.a.paused&&SP.cur==='b-focus'"))
        await pg.set_input_files('#spPlayer .spFile',str(ROOT/'voice.wav'));await pg.wait_for_timeout(500)
        ok('свой трек загружен в категорию',await pg.evaluate("SP.st.tracks.length===1&&SP.st.tracks[0].cat==='focus'"))
        await pg.click('#spPlayer [data-sp=mute]');ok('«без звука» глушит музыку',await pg.evaluate('SP.a.muted&&SP.st.muted'))
        await pg.click('#spPlayer [data-sp=mute]');await pg.click('#spPlayer [data-sp=pause]')
        await pg.reload();await pg.wait_for_selector('#spPlayer .spMain');await pg.wait_for_timeout(800)
        ok('после перезагрузки свой трек на месте и музыка молчит',await pg.evaluate("SP.st.tracks.length===1&&SP.a.paused"))
        tid=await pg.evaluate('SP.st.tracks[0].id');ok('файл трека лежит в IndexedDB',await pg.evaluate(f"spGet('{tid}').then(b=>!!b&&b.size>1000)"))
        # Family Connection
        await pg.click('#nav [data-t=earth]');await pg.wait_for_timeout(800)
        await pg.click('#famUpload');await pg.fill('#pName','Папа');await pg.fill('#pRel','отец');await pg.set_input_files('#pPhoto',str(ROOT/'photo.png'));await pg.click('#pForm button[type=submit]');await pg.wait_for_timeout(400)
        ok('без согласия фото не сохраняется',await pg.evaluate('S.people.length')==2)
        await pg.check('#pOk');await pg.click('#pForm button[type=submit]');await pg.wait_for_timeout(1200)
        pid=await pg.evaluate('S.people[S.people.length-1].id')
        await pg.wait_for_function(f"!!(FAM.av['{pid}']||'').startsWith('data:image')",timeout=10000)
        ok('карточка с аватаром из фото и родством',await pg.evaluate(f"!!document.querySelector('[data-fam={pid}]')&&S.people.find(p=>p.id==='{pid}').rel==='отец'&&FAM.av['{pid}'].startsWith('data:image')"))
        await pg.select_option('#cWho',pid);await pg.fill('#cText','Сынок, мы тобой гордимся.');await pg.set_input_files('#cVoice',str(ROOT/'voice.wav'));await pg.check('#cOk');await pg.click('#capForm button[type=submit]');await pg.wait_for_timeout(500)
        await pg.click(f'[data-fam={pid}]');await pg.wait_for_timeout(600);ok('окно аватара открывается',await pg.evaluate("document.querySelector('#famModal').classList.contains('on')"))
        await pg.click('[data-fplay]')
        vu=await pg.evaluate('''()=>new Promise(res=>{let mx=0,n=0;const iv=setInterval(()=>{mx=Math.max(mx,+getComputedStyle(document.documentElement).getPropertyValue('--vu')||0);if(++n>30){clearInterval(iv);res(mx)}},60)})''')
        ok('голос играет, ореол аватара реагирует на громкость',vu>0.15,vu)
        await pg.click('[data-ftab=gal]');await pg.set_input_files('#famGalIn',str(ROOT/'photo.png'));await pg.wait_for_timeout(500)
        ok('фото в семейную галерею',await pg.evaluate('document.querySelectorAll(".fmGal img").length')==1)
        await pg.click('[data-ftab=reply]');await pg.click('#famRec');await pg.wait_for_timeout(1200);await pg.click('#famRec');await pg.wait_for_timeout(500);await pg.fill('#famRText','Папа, у меня всё хорошо');await pg.click('#famSend')
        ok('Record a Message: ответ в очереди с голосом',await pg.evaluate(f"(()=>{{const r=S.replies[S.replies.length-1];return r.to==='{pid}'&&!!MEDIA['reply:'+r.id]}})()"))
        await pg.screenshot(path=str(OUT/'fam_modal.png'));await pg.click('.fmClose')
        s0=await pg.evaluate('solNow()+5');await pg.click(f'[data-csol="{s0}"]');await pg.fill('#dtT','Звонок с бабушкой');await pg.click('#dtForm button[type=submit]');await pg.wait_for_timeout(300)
        ok('событие в календаре семьи',await pg.evaluate(f"!!document.querySelector('[data-csol=\"{s0}\"] .dB')"))
        await pg.wait_for_timeout(1500);await pg.screenshot(path=str(OUT/'fam_room.png'))
        # Mission Games
        await pg.click('#nav [data-t=games]');await pg.wait_for_timeout(500);x0=await pg.evaluate('S.xp')
        await pg.click('[data-g=crew]');await pg.click('[data-cm=move]');ok('Crew Mission: задание даёт XP',await pg.evaluate('S.xp')==x0+10)
        for k in ['sleep','measure','rest','talk']:await pg.click(f'[data-cm={k}]')
        ok('все задания сола: бонус и награда',await pg.evaluate("S.xp")==x0+70 and await pg.evaluate("!!S.ach.crew"))
        await pg.evaluate('S.hist.push({...today(),sol:solNow()+1});S.hist.push({...today(),sol:solNow()+1});renderAll()')
        ok('пропущенные солы не отнимают XP',await pg.evaluate('S.xp')==x0+70)
        await pg.click('[data-g=garden]');g0=await pg.evaluate('gardenScore().total');await pg.click('#gWater');await pg.wait_for_timeout(1000)
        ok('Space Garden растёт от привычки',await pg.evaluate('gardenScore().total')==g0+1 and await pg.evaluate('GR.h[2]>0'))
        await pg.click('[data-g=memory]');await pg.click('#seqGo')
        for r in range(3):
            await pg.wait_for_function('!SQ.busy&&SQ.on',timeout=20000)
            for i in await pg.evaluate('SQ.seq'): await pg.click(f'[data-pl="{i}"]')
            await pg.wait_for_timeout(700)
        ok('Memory Universe: уровень 1 пройден',await pg.evaluate('S.seqBest')>=1)
        await pg.click('[data-g=earthmem]');await pg.wait_for_timeout(300);await pg.click('[data-em=sea]');ok('Earth Memories: место отмечено',await pg.evaluate("S.emem.sea===solNow()"))
        await pg.click('[data-g=breath]');await pg.wait_for_timeout(400);await pg.screenshot(path=str(OUT/'games.png'))
        ok('нет пропущенных ключей перевода',await pg.evaluate('Object.keys(MISS).length')==0,await pg.evaluate('Object.keys(MISS)'))
        await pg.click('#nav [data-t=over]');await pg.wait_for_timeout(1500);await pg.screenshot(path=str(OUT/'overview.png'))
        # телефон и сайт экипажа
        await pg.set_viewport_size({'width':390,'height':844})
        for tb in ['over','earth','games']:
            await pg.click(f'#nav [data-t={tb}]');await pg.wait_for_timeout(700)
            ok(f'телефон: {tb} без горизонтальной прокрутки',await pg.evaluate('document.documentElement.scrollWidth<=innerWidth'))
        await pg.screenshot(path=str(OUT/'phone_games.png'))
        await pg.goto(CREW);await pg.wait_for_selector('#spPlayer .spMain');await pg.wait_for_timeout(800)
        ok('сайт экипажа: тот же плеер и шрифт',await pg.evaluate("!!document.querySelector('#spPlayer')&&getComputedStyle(document.body).fontFamily.includes('Manrope')"))
        await pg.set_viewport_size({'width':1440,'height':900});await pg.wait_for_timeout(800);await pg.screenshot(path=str(OUT/'crew_theme.png'))
        for n,c,x in R:print(('OK  ' if c else 'FAIL'),n,('| '+str(x)) if x!='' else '')
        print('errors:',errs[:6]);await b.close();sys.exit(0 if all(c for _,c,_ in R) and not errs else 1)
asyncio.run(main())
